-- Generated by Loom
-- Generator: satellite
-- View: current state of sat_customer_details
SELECT
    customer_hk,
    customer_name,
    customer_email,
    __loaded_at,
    __record_source
FROM (
    SELECT
        customer_hk,
        customer_name,
        customer_email,
        __loaded_at,
        __record_source,
        ROW_NUMBER() OVER (
            PARTITION BY customer_hk
            ORDER BY __loaded_at DESC, __hash_diff DESC
        ) AS rn
    FROM {{ ref('sat_customer_details') }}
) AS ranked
WHERE rn = 1
